 .workspace{height:calc(100dvh - 64px);padding:12px 18px;gap:16px;align-items:stretch}
 .observation{position:relative;top:auto;align-self:stretch;min-height:0;display:grid;grid-template-rows:minmax(0,1fr) repeat(5,auto);gap:6px}
 #view:not(:fullscreen):not(.is-fullscreen){height:auto;min-height:0;max-height:none}
 .readings{padding:8px 0 7px}.metric-label{margin-bottom:4px}.reading strong{font-size:28px}.reading>small{margin-top:3px}.wind-meter{margin-top:6px}.direction-line{height:32px}.direction-line strong{font-size:19px}
 .observation-bottom{margin:0}.observation-bottom .quiet{padding:5px 8px;min-height:28px}
 .status-row{gap:8px 18px}.status-row .sea-readout,.status-row .damage-readout{padding-top:2px;padding-bottom:0}.status-row .sea-readout{gap:3px 14px}.status-row .damage-readout{gap:2px}
 .observer-controls{margin:0 3px;gap:5px 14px}.flight-settings{margin:0 3px;gap:12px}.flight-settings label{gap:4px}
 .controls{height:100%;min-height:0;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;scrollbar-width:thin;scrollbar-color:#46605f transparent}
 .settings-toggle{position:sticky;top:0;z-index:1}.sidebar-collapsed .controls{overflow:hidden}
}
/* Grid interpolation lets the scene grow while the sidebar folds. */
.workspace{transition:grid-template-columns .28s cubic-bezier(.22,.7,.3,1)}
.settings-body{display:grid;grid-template-rows:1fr;transition:grid-template-rows .28s cubic-bezier(.22,.7,.3,1)}
.settings-content{min-height:0;overflow:hidden;opacity:1;visibility:visible;transition:opacity .18s ease,visibility .28s}
.sidebar-collapsed .settings-body{grid-template-rows:0fr}.sidebar-collapsed .settings-content{opacity:0;visibility:hidden;pointer-events:none}
/* Native details keep keyboard semantics and animate in both directions. */
@supports (interpolate-size:allow-keywords){
 details{interpolate-size:allow-keywords}
 details::details-content{block-size:0;overflow:clip;opacity:0;transition:block-size .26s cubic-bezier(.22,.7,.3,1),opacity .2s ease,content-visibility .26s allow-discrete}
 details[open]::details-content{block-size:auto;opacity:1}
}
/* Temporary view panels and dialogs also fade on entry and exit. */
@supports (transition-behavior:allow-discrete){
 .camera-toolbar,.hud-settings,.hud-map-wrap{transition:opacity .2s ease,translate .2s ease,display .2s allow-discrete}
 @media(max-width:1000px),(pointer:coarse){
  #view:not(.controls-open) .camera-toolbar,#view:not(.display-open) .hud-settings,#view:not(.mobile-map-open) .hud-map-wrap{opacity:0;translate:0 6px;pointer-events:none}
 }
 dialog{transition:opacity .2s ease,translate .2s ease,display .2s allow-discrete,overlay .2s allow-discrete}
 dialog:not([open]){opacity:0;translate:0 8px}
 @starting-style{dialog[open],#view.controls-open .camera-toolbar,#view.display-open .hud-settings,#view.mobile-map-open .hud-map-wrap{opacity:0;translate:0 6px}}
}
@media(prefers-reduced-motion:reduce){.workspace,.settings-body,.settings-content,details::details-content,.camera-toolbar,.hud-settings,.hud-map-wrap,dialog{transition:none!important}}
/* Every settings category shares the same header, inset and separator spacing. */
.settings-content>.control-group{margin:0;padding:0 0 12px;border:0;border-bottom:1px solid var(--line)}
.settings-content>.control-group:not([open]){padding-bottom:0}
.settings-content>.control-group>summary{display:grid;grid-template-columns:14px minmax(0,1fr) auto;gap:8px;min-height:46px;align-items:center;padding:0 2px}
.settings-content>.control-group>summary h2{margin:0;letter-spacing:1px}
.settings-content>.control-group>summary>span{text-align:right}
.settings-content>.control-group>summary::before{justify-self:center}
#settingsPanel{overflow-anchor:none}
.guide-spotlight{border:3px solid #ffe179;outline:2px solid #13262d;border-radius:9px;box-shadow:0 0 0 5px #ffe17944,0 0 24px #ffd34f88,inset 0 0 12px #ffe17922;animation:guide-beacon 1.4s ease-in-out infinite}
@keyframes guide-beacon{0%,100%{border-color:#ffdd60;box-shadow:0 0 0 5px #ffe17933,0 0 12px #ffd34f55,inset 0 0 8px #ffe17911}50%{border-color:#fff8cf;box-shadow:0 0 0 6px #ffe17988,0 0 30px #ffd34fbb,inset 0 0 16px #ffe17933}}
@media(prefers-reduced-motion:reduce){.guide-spotlight{animation:none}}
.guide-footer{flex-wrap:wrap}.configuration-link{color:var(--accent);white-space:nowrap}

.formula-reference{width:min(1080px,calc(100vw - 24px));max-width:1080px;max-height:calc(100dvh - 24px);padding:24px;overflow:auto;box-sizing:border-box}
.formula-reference header{display:flex;justify-content:space-between;align-items:center;gap:16px}.formula-reference h2{font-size:23px;margin:0}.formula-reference-intro{font-size:12px;line-height:1.8;color:#b8cccf}
.formula-reference nav,.formula-reference-filters{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0;align-items:center}.formula-reference nav button[aria-pressed="true"]{border-color:#b6d4bd;background:#304c42}
.formula-reference-filters input{flex:1;min-width:160px}.formula-reference-filters select{max-width:100%}.formula-reference>p{font-size:12px}.formula-reference article{border-top:1px solid #526c6b66;padding:16px 0}.formula-reference h3{font-size:15px;margin:0 0 6px;overflow-wrap:anywhere}.formula-reference small{color:#89a4a8;font-size:11px;overflow-wrap:anywhere}.formula-reference article p{font-size:12px;overflow-wrap:anywhere}
.formula-reference pre{font:12px/1.7 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#10191d;padding:12px;max-width:100%;box-sizing:border-box;tab-size:2}.formula-reference-source{border-top:1px solid #526c6b66;padding:12px 0}.formula-reference-source summary{cursor:pointer;overflow-wrap:anywhere}
@media(max-width:600px){.formula-reference{padding:16px}.formula-reference h2{font-size:19px}.formula-reference header button{flex-shrink:0}.formula-reference-filters>*{width:100%}.formula-reference nav button{min-height:42px}}
